import { SetMetadata } from '@nestjs/common';
import { ON_QUEUE_EVENT_METADATA } from '../bull.constants.js';
/**
 * Registers a queue event listener.
 * Class that contains queue event listeners must be annotated
 * with the "QueueEventsListener" decorator.
 *
 * @publicApi
 */
export const OnQueueEvent = (eventName) => SetMetadata(ON_QUEUE_EVENT_METADATA, { eventName });
